// DOM layout: key elements located by role and name or by visible text, compared with the reference's
// boxes (layout.json, generated by tools/export-frames.mjs). See ../README.md "Metric".
import { locate } from './capture.mjs';

const POSITION_TOLERANCE = 16; // px: full credit within this, linearly down to 0 at 3x
const SIZE_SHARE = 0.05; // size tolerance: the larger of 16 px and 5% of the reference size
const SAME_ROW = 4; // px: boxes whose tops differ less than this are on the same row (ordered by x)

/** Page-coordinate boxes `{ x, y, width, height, fontSize, fontWeight }` of the frame's key elements; null for elements not found. */
export async function measure(page, specs) {
  const boxes = {};
  for (const spec of specs) {
    const element = locate(page, spec);
    boxes[spec.id] = (await element.count())
      ? await element.evaluate((node) => {
        const rect = node.getBoundingClientRect();
        const style = getComputedStyle(node);
        return { x: Math.round(rect.x + window.scrollX), y: Math.round(rect.y + window.scrollY), width: Math.round(rect.width), height: Math.round(rect.height), fontSize: Number.parseFloat(style.fontSize), fontWeight: Number(style.fontWeight) };
      }).catch(() => null)
      : null;
  }
  return boxes;
}

const credit = (error, tolerance) => Math.min(1, Math.max(0, 1 - (error - tolerance) / (2 * tolerance)));
const before = (a, b) => (Math.abs(a.y - b.y) < SAME_ROW ? a.x - b.x : a.y - b.y);

/**
 * Scores measured boxes against reference boxes (both `{ id: box | null }`): per element, 0 when
 * missing, else the mean of position credit (top-left corner), size credit and type credit (font
 * size within 1 px, down to 0 at 3 px; weight equal, half credit 100 off, none 200 off); the frame score is
 * 0.8 x the element mean + 0.2 x the order score (share of neighbouring pairs, in reference reading
 * order, that keep their order) x the share of elements found.
 */
export function scoreLayout(reference, measured) {
  const ids = Object.keys(reference).filter((id) => reference[id]);
  const elements = {};
  for (const id of ids) {
    const want = reference[id];
    const got = measured[id];
    if (!got) {
      elements[id] = 0;
      continue;
    }
    const position = credit(Math.max(Math.abs(got.x - want.x), Math.abs(got.y - want.y)), POSITION_TOLERANCE);
    const size = Math.min(
      credit(Math.abs(got.width - want.width), Math.max(16, SIZE_SHARE * want.width)),
      credit(Math.abs(got.height - want.height), Math.max(16, SIZE_SHARE * want.height))
    );
    const type = (credit(Math.abs(got.fontSize - want.fontSize), 1) + Math.max(0, 1 - Math.abs(got.fontWeight - want.fontWeight) / 200)) / 2;
    elements[id] = (position + size + type) / 3;
  }
  const found = ids.filter((id) => measured[id]);
  const inOrder = [...found].sort((a, b) => before(reference[a], reference[b]));
  let kept = 0;
  for (let index = 1; index < inOrder.length; index += 1) if (before(measured[inOrder[index - 1]], measured[inOrder[index]]) <= 0) kept += 1;
  const order = inOrder.length > 1 ? kept / (inOrder.length - 1) : found.length ? 1 : 0;
  const mean = ids.length ? ids.reduce((sum, id) => sum + elements[id], 0) / ids.length : 0;
  const coverage = ids.length ? found.length / ids.length : 0;
  return { score: 0.8 * mean + 0.2 * order * coverage, coverage, order, elements };
}
